import {attachResendRow} from './admin-document-rows.mjs';
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export function resendPanel(order,api,onSent,rows){const box=el('section'),tools=el('div'),review=el('div'),feedback=el('p');box.className='order-resend';tools.className='resend-tools';feedback.setAttribute('role','status');if(rows)box.append(feedback,review);else box.append(el('h3','Send til kunden'),tools,feedback,review);let generation=0;
async function preview(action,button){const current=++generation;review.replaceChildren();feedback.textContent='Henter forhåndsvisning…';button.disabled=true;try{const d=await(await api(`/api/pf-orders/${order.id}/resend`,'POST',{action})).json();if(current!==generation)return;feedback.textContent='';review.append(el('h3','Gennemse før afsendelse'),el('p','Til: '+d.to),el('strong',d.subject),el('pre',d.text));for(const a of d.attachments){const link=el('a','Åbn bilag: '+a.name);link.href=`/api/pf-orders/${order.id}/resend/${d.id}/attachment/${a.index}`;link.target='_blank';link.rel='noopener';review.append(link);}if(!d.attachments.length)review.append(el('small','Ingen vedhæftede bilag.'));const send=el('button','Send til '+d.to),cancel=el('button','Luk forhåndsvisning');send.type=cancel.type='button';cancel.onclick=()=>{generation++;review.replaceChildren();};send.onclick=async()=>{send.disabled=true;cancel.disabled=true;try{const result=await(await api(`/api/pf-orders/${order.id}/resend`,'POST',{draftId:d.id})).json();feedback.textContent=result.status==='sent'?'Mailen er accepteret af mailserveren.':result.error||'Afsendelsen er ikke bekræftet. Kontrollér historikken.';review.replaceChildren();await onSent();}catch(e){feedback.textContent=e.message;await onSent();cancel.disabled=false;}};review.append(send,cancel);}catch(e){feedback.textContent=e.message;}finally{button.disabled=false;}}
if(rows?.checkout?.paymentProvider==='bank_transfer'){
 const checkout=rows.checkout,row=rows.ensure('invoice'),button=el('button',checkout.bankPayment?.invoicedAt?'✓ Faktura sendt':'Faktura sendt');button.type='button';button.disabled=Boolean(checkout.bankPayment?.invoicedAt);row.actions.append(button);
 button.onclick=async()=>{if(!confirm('Har du sendt fakturaen til kunden fra hello@smerch.dk?'))return;button.disabled=true;try{const response=await api(`/api/admin/checkouts/${checkout.id}/bank-payment`,'POST',{action:'invoice_sent',confirmed:true}),result=await response.json();if(response.ok===false||result.error)throw Error(result.error||'Kunne ikke gemme markeringen.');button.textContent='✓ Faktura sendt';row.setSent('manual-invoice',{status:'sent',manual:true,to:rows.billing,sentAt:new Date().toISOString()});feedback.textContent='Fakturaen er markeret som manuelt sendt.';try{await onSent();}catch{feedback.textContent+=' Opdatér siden for at se den gemte status.';}}catch(e){feedback.textContent=e.message;button.disabled=false;}};
}
api(`/api/pf-orders/${order.id}/resend`).then(r=>r.json()).then(options=>{for(const o of options){if(o.action==='invoice')continue;const wrap=el('div'),button=el('button',o.label);button.type='button';button.disabled=!o.available;button.onclick=()=>preview(o.action,button);if(rows)attachResendRow(rows,o,button);else{wrap.append(button);if(o.reason)wrap.append(el('small',o.reason));tools.append(wrap);}}}).catch(e=>{feedback.textContent='Handlingerne kunne ikke indlæses: '+e.message;});return box;}
